const extract = (res) => {
  if (res && Array.isArray(res.scenes)) return res;
  let raw = res?.content?.parts?.[0]?.text ?? res?.parts?.[0]?.text ?? res?.text ?? res?.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  raw = raw.split('```json').join('').split('```').join('').trim();
  try { return JSON.parse(raw); } catch (e) {
    const found = [];
    const re = /[{][^{}]*"narration"[^{}]*[}]/g;
    let m;
    while ((m = re.exec(raw)) !== null) { try { found.push(JSON.parse(m[0])); } catch (_) {} }
    const pick = (k) => { const x = raw.match(new RegExp('"' + k + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*"')); return x ? x[1] : ''; };
    return { title: pick('title'), thumbnail_text: pick('thumbnail_text'), language: pick('language') || 'en', music_mood: pick('music_mood'), scenes: found };
  }
};
const a = extract($('Write script').first().json) || {};
const b = extract($input.first().json) || {};
const scenes = [].concat(a.scenes || [], b.scenes || []);
const cfg = $('Video settings').first().json;
if (scenes.length < Math.max(3, Math.ceil((Number(cfg.scene_count) || 0) * 0.8))) {
  throw new Error('Merged script has ' + scenes.length + ' of ' + cfg.scene_count + ' scenes (a half was cut off). It will retry on the next run.');
}
return [{ json: Object.assign({}, a, { scenes }) }];
